    using System;

class GfG {

    // Function to partition the array according 
    // to pivot index element
    static void partition(int[] arr) {
        int n = arr.Length, temp;
        int pivot = arr[n - 1];

        // i acts as boundary between smaller and 
        // larger element compared to pivot
        int i = -1;
        for (int j = 0; j < n; j++) {

            // If smaller element is found expand the 
            // boundary and swapping it with boundary element.
            if (arr[j] < pivot) {
                i++;
                temp = arr[i];
                arr[i] = arr[j];
                arr[j] = temp;
            }
        }

        // place the pivot at its correct position
        temp = arr[i+1];
        arr[i+1] = arr[n-1];
        arr[n-1] = temp;
    }

    static void Main() {
        int[] arr = {5, 13, 6, 9, 12, 11, 8};
        partition(arr);

        Console.WriteLine(string.Join(" ", arr));
    }
}


            JavaScript

    function partition(arr) {
    let n = arr.length;
    let pivot = arr[n - 1];

    // i acts as boundary between smaller and 
    // larger element compared to pivot
    let i = -1;
    for (let j = 0; j < n; j++) {

        // If smaller element is found expand the 
        // boundary and swapping it with boundary element.
        if (arr[j] < pivot) {
            i++;
            [arr[i], arr[j]] = [arr[j], arr[i]];
        }
    }

    // place the pivot at its correct position
    [arr[i + 1], arr[n - 1]] = [arr[n - 1], arr[i + 1]];
}

// Driver Code
